import assert from 'node:assert/strict';
import {readFile,writeFile} from 'node:fs/promises';
import {parseEnv} from 'node:util';
import {createHash} from 'node:crypto';
import {setTimeout as sleep} from 'node:timers/promises';
const env=parseEnv(await readFile('.env.local','utf8'));
for(const name of ['JEV_API_KEY','JEV_GATEWAY_URL','JEV_MODEL_ID','JEV_MODEL_VERSION']) process.env[name]=env[name];
assert.equal(process.env.JEV_MODEL_ID,'typesafe-ai/jev');
const corpus=JSON.parse(await readFile('scripts/fixtures/jev-semantics.json','utf8'));
const {classifyEmailAgainstTags}=await import('../../src/lib/jev.ts');
const fetchOriginal=globalThis.fetch;
const calls=[];
let current;
globalThis.fetch=async (url,init)=>{
 assert.equal(url,'https://ai-gateway.vercel.sh/v4/ai/evaluation-model');
 assert.equal(new Headers(init.headers).get('ai-model-id'),'typesafe-ai/jev');
 const payload=JSON.parse(init.body);
 assert.equal(payload.providerOptions.gateway.zeroDataRetention,true);
 assert.equal(payload.providerOptions.gateway.disallowPromptTraining,true);
 const start=performance.now();
 const response=await fetchOriginal(url,{...init,redirect:'error'});
 const raw=await response.clone().json();
 calls.push({caseId:current,status:response.status,latencyMs:Math.round(performance.now()-start),answers:raw.answers??null,cost:raw.providerMetadata?.gateway?.cost??null,retryAfter:response.headers.get('retry-after'),requestSha256:createHash('sha256').update(init.body).digest('hex')});
 return response;
};
const ids=['limit-01','limit-02','limit-03','limit-05','limit-07','unknown-01'];
const rows=[];
const startedAt=new Date().toISOString();
try{
 for(const [i,id]of ids.entries()){
  if(i)await sleep(13000);
  current=id;
  const c=corpus.cases.find(c=>c.id===id);
  const r=corpus.rules.find(r=>r.id===c.rule);
  const tags=['plain','rephrased','hints','misleading_hints'].map(v=>({id:v,name:r.name,prompt:v==='rephrased'?r.paraphrase:r.prompt,keywords:v==='hints'?r.keywords:v==='misleading_hints'?['message','your','the','free','newsletter']:[],senders:v==='misleading_hints'?['person@example.net']:[]}));
  let results;
  for(let attempt=0;attempt<3;attempt++){
   try{results=await classifyEmailAgainstTags(c.email,tags);break;}
   catch(e){if(e.statusCode!==429||attempt===2)throw new Error('Followup inference failed: '+e.name);await sleep((Number(calls.at(-1).retryAfter)||60)*1000+1000);}
  }
  rows.push({caseId:id,expected:c.expected,results});
  console.log(JSON.stringify({id,expected:c.expected,results:Object.fromEntries(Object.entries(results).map(([k,v])=>[k,{decision:v.decision,confidence:v.confidence}]))}));
 }
}finally{
 globalThis.fetch=fetchOriginal;
 await writeFile('test-results/jev-semantics/followup.json',JSON.stringify({startedAt,completedAt:new Date().toISOString(),purpose:'Exploratory exact-app checks selected after grouped input-limit failures; excluded from primary scores.',ids,rows,calls,source:await readFile('test-results/jev-semantics/followup.mjs','utf8')},null,2)+'\n');
}
